export type ResizeRect = { x: number; y: number; width: number; height: number };
export type ResizePoint = { x: number; y: number };
export type ResizeHandleName = "n" | "ne" | "e" | "se" | "s" | "sw" | "w" | "nw";

/** The dragged edges, in the rect's units. An axis the handle does not move is left out. */
export type ResizeEdges = { x?: number; y?: number };
export type ResizeSnap = (edges: ResizeEdges, handle: ResizeHandleName) => ResizeEdges;

export type ResizeLimits = {
  minWidth?: number;
  minHeight?: number;
  maxWidth?: number;
  maxHeight?: number;
};

export type ResizeOptions = ResizeLimits & {
  /** Keeps width divided by height at this value. */
  aspectRatio?: number;
  /** Grows both sides equally, so the centre stays put. */
  fromCenter?: boolean;
  /** Places dragged edges on multiples of this value. */
  step?: number;
  /** Moves dragged edges, for example to your alignment guides. Limits still apply afterwards. */
  snap?: ResizeSnap;
};

export const cornerHandles: ResizeHandleName[] = ["nw", "ne", "se", "sw"];
export const edgeHandles: ResizeHandleName[] = ["n", "e", "s", "w"];

/** Which way each handle moves: x is -1 left, 1 right; y is -1 up, 1 down. */
export const handleAxes: Record<ResizeHandleName, readonly [number, number]> = {
  n: [0, -1],
  ne: [1, -1],
  e: [1, 0],
  se: [1, 1],
  s: [0, 1],
  sw: [-1, 1],
  w: [-1, 0],
  nw: [-1, -1],
};

const clamp = (value: number, min: number, max: number) => Math.min(Math.max(value, min), Math.max(min, max));

export const sameRect = (a: ResizeRect, b: ResizeRect) => a.x === b.x && a.y === b.y && a.width === b.width && a.height === b.height;

export function resolveHandles(handles: "all" | "corners" | "edges" | ResizeHandleName[]) {
  if (handles === "all") return [...cornerHandles, ...edgeHandles];
  if (handles === "corners") return cornerHandles;
  if (handles === "edges") return edgeHandles;
  return handles;
}

/** The rect after moving a handle by `delta`. It never flips: past the opposite edge it stops at the minimum size. */
export function resizeRect(start: ResizeRect, handle: ResizeHandleName, delta: ResizePoint, options: ResizeOptions = {}): ResizeRect {
  const { minWidth = 1, minHeight = 1, maxWidth = Infinity, maxHeight = Infinity, aspectRatio, fromCenter = false, step, snap } = options;
  const [dirX, dirY] = handleAxes[handle];
  const right = start.x + start.width;
  const bottom = start.y + start.height;
  const centerX = start.x + start.width / 2;
  const centerY = start.y + start.height / 2;
  const onGrid = (value: number) => (step && step > 0 ? Math.round(value / step) * step : value);

  let edges: ResizeEdges = {
    x: dirX ? onGrid((dirX > 0 ? right : start.x) + delta.x) : undefined,
    y: dirY ? onGrid((dirY > 0 ? bottom : start.y) + delta.y) : undefined,
  };
  if (snap) {
    const snapped = snap(edges, handle);
    edges = { x: dirX ? (snapped.x ?? edges.x) : undefined, y: dirY ? (snapped.y ?? edges.y) : undefined };
  }

  const span = (edge: number, dir: number, low: number, high: number, center: number) => (fromCenter ? dir * (edge - center) * 2 : dir * (edge - (dir > 0 ? low : high)));
  let width = edges.x === undefined ? start.width : span(edges.x, dirX, start.x, right, centerX);
  let height = edges.y === undefined ? start.height : span(edges.y, dirY, start.y, bottom, centerY);

  if (aspectRatio && aspectRatio > 0) {
    const change = (value: number, from: number) => (from > 0 ? Math.abs(value / from - 1) : 0);
    // A corner follows whichever axis moved furthest; an edge follows its own axis.
    const widthLeads = dirY === 0 || (dirX !== 0 && change(width, start.width) >= change(height, start.height));
    width = clamp(widthLeads ? width : height * aspectRatio, Math.max(minWidth, minHeight * aspectRatio), Math.min(maxWidth, maxHeight * aspectRatio));
    height = width / aspectRatio;
  } else {
    width = clamp(width, minWidth, maxWidth);
    height = clamp(height, minHeight, maxHeight);
  }

  const place = (dir: number, low: number, high: number, center: number, size: number) => {
    if (fromCenter || dir === 0) return center - size / 2;
    return dir > 0 ? low : high - size;
  };
  return { x: place(dirX, start.x, right, centerX, width), y: place(dirY, start.y, bottom, centerY, height), width, height };
}

"use client";

import { type ComponentPropsWithoutRef, type ReactNode, forwardRef } from "react";
import { type ResizeHandleName, cornerHandles } from "./resize-handles-math";
import { useResizeHandles } from "./resize-handles-state";
import { cn } from "@/lib/utils";

const placement: Record<ResizeHandleName, string> = {
  nw: "top-0 left-0 cursor-nwse-resize",
  ne: "top-0 left-full cursor-nesw-resize",
  se: "top-full left-full cursor-nwse-resize",
  sw: "top-full left-0 cursor-nesw-resize",
  n: "top-0 inset-x-2 h-2 -translate-y-1/2 cursor-ns-resize pointer-coarse:inset-x-3.5 pointer-coarse:h-4",
  s: "top-full inset-x-2 h-2 -translate-y-1/2 cursor-ns-resize pointer-coarse:inset-x-3.5 pointer-coarse:h-4",
  e: "left-full inset-y-2 w-2 -translate-x-1/2 cursor-ew-resize pointer-coarse:inset-y-3.5 pointer-coarse:w-4",
  w: "left-0 inset-y-2 w-2 -translate-x-1/2 cursor-ew-resize pointer-coarse:inset-y-3.5 pointer-coarse:w-4",
};

export const handleCursor: Record<ResizeHandleName, string> = { nw: "nwse-resize", se: "nwse-resize", ne: "nesw-resize", sw: "nesw-resize", n: "ns-resize", s: "ns-resize", e: "ew-resize", w: "ew-resize" };

type HandleProps = {
  name: ResizeHandleName;
  className?: string;
  /** Shows a mark on an edge handle, for selections without corners. */
  edgeMark?: boolean;
  children?: ReactNode;
};

// Solid while idle so the outline never shows through a mark. Marks sit on canvas content rather than app
// chrome, so they default to white as in design tools; set --resize-handle-fill to change it. Accent while acting.
const markFill = "border border-primary bg-[var(--resize-handle-fill,#fff)] group-[:focus-visible:not([data-pointer-focus])]/resize:bg-primary group-data-resizing/resize:bg-primary";

/** One pointer target. Keyboard users resize through the root, so handles stay out of the tab order. Marks fill on keyboard focus and while resizing. */
export function ResizeHandleTarget({ name, className, edgeMark = false, children }: HandleProps) {
  const corner = cornerHandles.includes(name);
  const horizontal = name === "n" || name === "s";
  return (
    <div
      aria-hidden
      data-slot="resize-handle"
      data-handle={name}
      data-canvas-no-pan=""
      className={cn(
        "pointer-events-auto absolute z-10 touch-none select-none",
        corner && "grid size-4 -translate-x-1/2 -translate-y-1/2 place-items-center pointer-coarse:size-7",
        placement[name],
        className,
      )}
    >
      {children ??
        (corner ? (
          <span data-slot="resize-handle-mark" className={cn("size-1.5 pointer-coarse:size-2.5", markFill)} />
        ) : edgeMark ? (
          <span
            data-slot="resize-handle-mark"
            className={cn("absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2", markFill, horizontal ? "h-1.5 w-4 pointer-coarse:h-2.5 pointer-coarse:w-6" : "h-4 w-1.5 pointer-coarse:h-6 pointer-coarse:w-2.5")}
          />
        ) : null)}
    </div>
  );
}

type LabelProps = ComponentPropsWithoutRef<"span">;

/** The live size, below the outline. Pass children to replace the text. */
export const ResizeHandlesLabel = forwardRef<HTMLSpanElement, LabelProps>(function ResizeHandlesLabel({ className, children, ...props }, ref) {
  const { rect, messages } = useResizeHandles();
  return (
    <span
      ref={ref}
      data-slot="resize-handles-label"
      className={cn("absolute top-full left-1/2 mt-2 -translate-x-1/2 rounded-sm bg-primary px-1.5 py-0.5 text-[10px] leading-3 font-medium whitespace-nowrap text-primary-foreground tabular-nums", className)}
      {...props}
    >
      {children ?? messages.size(Math.round(rect.width), Math.round(rect.height))}
    </span>
  );
});

"use client";

import { type KeyboardEvent, type MouseEvent, type PointerEvent, forwardRef, useCallback, useEffect, useId, useMemo, useRef, useState } from "react";
import { type ResizeHandleName, type ResizeOptions, type ResizeRect, cornerHandles, handleAxes, resizeRect, resolveHandles, sameRect } from "./resize-handles-math";
import { ResizeHandleTarget, handleCursor } from "./resize-handles-parts";
import { type Drag, type ResizeDetail, type ResizeHandlesProps, type ResizeTransform, ResizeHandlesContext, defaultMessages, toRectPoint, useIsomorphicLayoutEffect } from "./resize-handles-state";
import { cn } from "@/lib/utils";

const identity: ResizeTransform = { panX: 0, panY: 0, zoom: 1 };
/** Below this on-screen size, edge handles would crowd the corners. */
const compactSize = 40;
const arrowKeys: Record<string, readonly [number, number]> = { ArrowLeft: [-1, 0], ArrowRight: [1, 0], ArrowUp: [0, -1], ArrowDown: [0, 1] };

/** An outline with resize handles around a rect. Your app owns the rect and receives live and committed sizes. */
export const ResizeHandles = forwardRef<HTMLDivElement, ResizeHandlesProps>(function ResizeHandles(
  {
    rect,
    onRectChange,
    onRectCommit,
    onResizingChange,
    transform = identity,
    handles = "all",
    minWidth,
    minHeight,
    maxWidth,
    maxHeight,
    aspectRatio,
    step = 1,
    snap,
    disabled = false,
    renderHandle,
    handleClassName,
    messages: messageOverrides,
    className,
    style,
    children,
    onBlur,
    onClick,
    onKeyDown,
    onPointerDown,
    onPointerMove,
    onPointerUp,
    onPointerCancel,
    onLostPointerCapture,
    ...props
  },
  ref,
) {
  const messages = useMemo(() => ({ ...defaultMessages, ...messageOverrides }), [messageOverrides]);
  const instructionsId = useId();
  const [activeHandle, setActiveHandle] = useState<ResizeHandleName | null>(null);
  const [announcement, setAnnouncement] = useState("");
  // Focus from a drag can still count as keyboard focus in the browser, so it is tracked separately.
  const [pointerFocus, setPointerFocus] = useState(false);
  const drag = useRef<Drag | null>(null);
  const options: ResizeOptions = { minWidth, minHeight, maxWidth, maxHeight, aspectRatio, step, snap };
  const latest = useRef({ options, transform, messages, onRectChange, onRectCommit, onResizingChange });
  useIsomorphicLayoutEffect(() => {
    latest.current = { options, transform, messages, onRectChange, onRectCommit, onResizingChange };
  });

  const announce = (next: ResizeRect) => setAnnouncement(latest.current.messages.size(Math.round(next.width), Math.round(next.height)));

  const update = useCallback((active: Drag) => {
    const { options: current, transform: view, onRectChange: change } = latest.current;
    const point = toRectPoint(active.client, active.root, view);
    const ratio = active.start.width > 0 && active.start.height > 0 ? active.start.width / active.start.height : undefined;
    const next = resizeRect(active.start, active.handle, { x: point.x - active.origin.x, y: point.y - active.origin.y }, { ...current, aspectRatio: current.aspectRatio ?? (active.shift ? ratio : undefined), fromCenter: active.alt });
    if (sameRect(next, active.last)) return;
    active.last = next;
    change(next, { handle: active.handle, source: "pointer" });
  }, []);

  const finish = useCallback((cancel: boolean) => {
    const active = drag.current;
    if (!active) return;
    drag.current = null;
    const detail: ResizeDetail = { handle: active.handle, source: "pointer" };
    const changed = !sameRect(active.last, active.start);
    if (changed && cancel) latest.current.onRectChange(active.start, detail);
    if (changed && !cancel) {
      latest.current.onRectCommit?.(active.last, detail);
      setAnnouncement(latest.current.messages.size(Math.round(active.last.width), Math.round(active.last.height)));
    }
    setActiveHandle(null);
    latest.current.onResizingChange?.(false);
    if (active.element.hasPointerCapture?.(active.id)) active.element.releasePointerCapture(active.id);
  }, []);

  useEffect(() => {
    if (!activeHandle) return;
    const onKey = (event: globalThis.KeyboardEvent) => {
      const active = drag.current;
      if (!active) return;
      if (event.key === "Escape" && event.type === "keydown") {
        event.preventDefault();
        event.stopPropagation();
        finish(true);
      } else if (event.key === "Shift" || event.key === "Alt") {
        // Pressing or releasing a modifier applies at once, without waiting for the pointer to move.
        active.shift = event.shiftKey;
        active.alt = event.altKey;
        update(active);
      }
    };
    const onBlur = () => finish(true);
    // A handle your app removes mid-drag can no longer report the release, so the window ends the drag.
    const onPointerEnd = (event: globalThis.PointerEvent) => {
      if (drag.current?.id === event.pointerId) finish(event.type === "pointercancel");
    };
    const cursor = document.body.style.cursor;
    document.body.style.cursor = handleCursor[activeHandle];
    window.addEventListener("keydown", onKey, true);
    window.addEventListener("keyup", onKey, true);
    window.addEventListener("blur", onBlur);
    window.addEventListener("pointerup", onPointerEnd);
    window.addEventListener("pointercancel", onPointerEnd);
    return () => {
      document.body.style.cursor = cursor;
      window.removeEventListener("keydown", onKey, true);
      window.removeEventListener("keyup", onKey, true);
      window.removeEventListener("blur", onBlur);
      window.removeEventListener("pointerup", onPointerEnd);
      window.removeEventListener("pointercancel", onPointerEnd);
    };
  }, [activeHandle, finish, update]);

  useEffect(() => () => finish(true), [finish]);

  const enabled = disabled ? [] : resolveHandles(handles);
  const screen = { x: rect.x * transform.zoom + transform.panX, y: rect.y * transform.zoom + transform.panY, width: rect.width * transform.zoom, height: rect.height * transform.zoom };
  const corners = enabled.filter((handle) => cornerHandles.includes(handle));
  // The handle being dragged always stays, because removing it would end the pointer capture.
  const visible = Math.min(screen.width, screen.height) < compactSize && corners.length > 0 ? enabled.filter((handle) => corners.includes(handle) || handle === activeHandle) : enabled;

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    onKeyDown?.(event);
    if (event.defaultPrevented || event.target !== event.currentTarget || drag.current) return;
    const direction = arrowKeys[event.key];
    if (!direction) return;
    // An axis no handle can change stays fixed, and the key is left for the canvas.
    if (!enabled.some((handle) => handleAxes[handle].some((axis, index) => axis !== 0 && direction[index] !== 0))) return;
    event.preventDefault();
    event.stopPropagation();
    setPointerFocus(false);
    const amount = (step > 0 ? step : 1) * (event.shiftKey ? 10 : 1);
    const next = resizeRect(rect, "se", { x: direction[0] * amount, y: direction[1] * amount }, options);
    if (sameRect(next, rect)) return;
    const detail: ResizeDetail = { handle: "se", source: "keyboard" };
    onRectChange(next, detail);
    onRectCommit?.(next, detail);
    announce(next);
  };

  const handlePointerDown = (event: PointerEvent<HTMLDivElement>) => {
    onPointerDown?.(event);
    const element = (event.target as Element).closest<HTMLElement>("[data-handle]");
    const handle = element?.dataset.handle as ResizeHandleName | undefined;
    if (event.defaultPrevented || event.button !== 0 || !element || !handle || drag.current) return;
    event.preventDefault();
    event.stopPropagation();
    const root = event.currentTarget;
    setPointerFocus(true);
    root.focus({ preventScroll: true });
    const client = { x: event.clientX, y: event.clientY };
    drag.current = { id: event.pointerId, handle, start: rect, last: rect, origin: toRectPoint(client, root, transform), client, shift: event.shiftKey, alt: event.altKey, element, root };
    try {
      element.setPointerCapture?.(event.pointerId);
    } catch {
      // The pointer may already have ended; the window listener still finishes the drag.
    }
    setActiveHandle(handle);
    onResizingChange?.(true);
  };

  const handlePointerMove = (event: PointerEvent<HTMLDivElement>) => {
    onPointerMove?.(event);
    const active = drag.current;
    if (!active || active.id !== event.pointerId) return;
    active.client = { x: event.clientX, y: event.clientY };
    active.shift = event.shiftKey;
    active.alt = event.altKey;
    update(active);
  };

  // The click that ends a drag must not reach the canvas, where it would clear the selection.
  const handleClick = (event: MouseEvent<HTMLDivElement>) => {
    onClick?.(event);
    if ((event.target as Element).closest("[data-handle]")) event.stopPropagation();
  };

  return (
    <ResizeHandlesContext.Provider value={{ rect, resizing: activeHandle !== null, messages }}>
      <div
        ref={ref}
        role="group"
        aria-label={messages.label}
        aria-describedby={enabled.length > 0 ? instructionsId : undefined}
        aria-disabled={disabled || undefined}
        tabIndex={enabled.length > 0 ? 0 : undefined}
        data-slot="resize-handles"
        data-resizing={activeHandle ? "" : undefined}
        data-disabled={disabled ? "" : undefined}
        data-pointer-focus={pointerFocus ? "" : undefined}
        className={cn("group/resize pointer-events-none absolute outline-none", className)}
        style={{ ...style, left: screen.x, top: screen.y, width: screen.width, height: screen.height }}
        onBlur={(event) => {
          onBlur?.(event);
          setPointerFocus(false);
        }}
        onClick={handleClick}
        onKeyDown={handleKeyDown}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={(event) => {
          onPointerUp?.(event);
          if (drag.current?.id === event.pointerId) finish(false);
        }}
        onPointerCancel={(event) => {
          onPointerCancel?.(event);
          if (drag.current?.id === event.pointerId) finish(true);
        }}
        onLostPointerCapture={(event) => {
          onLostPointerCapture?.(event);
          if (drag.current?.id === event.pointerId) finish(true);
        }}
        {...props}
      >
        <span aria-hidden data-slot="resize-handles-outline" className="pointer-events-none absolute inset-0 border border-primary" />
        {visible.map((handle) => (
          <ResizeHandleTarget key={handle} name={handle} className={handleClassName} edgeMark={corners.length === 0}>
            {renderHandle?.(handle)}
          </ResizeHandleTarget>
        ))}
        {children}
        <span id={instructionsId} hidden>
          {messages.instructions}
        </span>
        <span role="status" className="sr-only">
          {announcement}
        </span>
      </div>
    </ResizeHandlesContext.Provider>
  );
});

"use client";

import { type ComponentPropsWithoutRef, type ReactNode, createContext, useContext, useEffect, useLayoutEffect } from "react";
import type { ResizeHandleName, ResizeLimits, ResizePoint, ResizeRect, ResizeSnap } from "./resize-handles-math";

export const useIsomorphicLayoutEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;

/** Replaceable text, for example to translate. */
export type ResizeHandlesMessages = {
  label: string;
  instructions: string;
  size: (width: number, height: number) => string;
};

export const defaultMessages: ResizeHandlesMessages = {
  label: "Resize selection",
  instructions: "Arrow keys change the size. Hold Shift for larger steps.",
  size: (width, height) => `${width} × ${height}`,
};

/** Where the rect's coordinates sit on screen. It has the same shape as Canvas Viewport's transform. */
export type ResizeTransform = { panX: number; panY: number; zoom: number };

/** A drag in progress. */
export type Drag = {
  id: number;
  handle: ResizeHandleName;
  start: ResizeRect;
  last: ResizeRect;
  origin: ResizePoint;
  client: ResizePoint;
  shift: boolean;
  alt: boolean;
  element: HTMLElement;
  root: HTMLElement;
};

/** A client point in the rect's units, so panning or zooming during a drag keeps the handle under the pointer. */
export function toRectPoint(client: ResizePoint, root: HTMLElement, { panX, panY, zoom }: ResizeTransform): ResizePoint {
  const parent = (root.offsetParent ?? root.parentElement) as HTMLElement | null;
  const box = parent?.getBoundingClientRect();
  const left = (box?.left ?? 0) + (parent?.clientLeft ?? 0);
  const top = (box?.top ?? 0) + (parent?.clientTop ?? 0);
  return { x: (client.x - left - panX) / zoom, y: (client.y - top - panY) / zoom };
}

/** How a resize happened: the handle used, and whether it came from the pointer or the keyboard. */
export type ResizeDetail = { handle: ResizeHandleName; source: "pointer" | "keyboard" };

export type ResizeHandlesProps = ComponentPropsWithoutRef<"div"> &
  ResizeLimits & {
    /** The object's position and size. Your app owns it. */
    rect: ResizeRect;
    /** Called with live rects while resizing, and with the starting rect when a drag is cancelled. */
    onRectChange: (rect: ResizeRect, detail: ResizeDetail) => void;
    /** Called once per finished drag or key press, for saving and undo. */
    onRectCommit?: (rect: ResizeRect, detail: ResizeDetail) => void;
    /** Reports when a drag starts and ends. */
    onResizingChange?: (resizing: boolean) => void;
    /** Maps the rect to the screen. Pass Canvas Viewport's transform on a canvas. */
    transform?: ResizeTransform;
    /** Which handles to show. */
    handles?: "all" | "corners" | "edges" | ResizeHandleName[];
    /** Locks width divided by height. Without it, Shift keeps the starting proportions. */
    aspectRatio?: number;
    /** Places dragged edges on multiples of this value. Arrow keys move by it, and by ten times it with Shift. */
    step?: number;
    /** Moves dragged edges, for example to your alignment guides. */
    snap?: ResizeSnap;
    /** Keeps the outline and turns off resizing. */
    disabled?: boolean;
    /** Replaces the visible mark of a corner or edge handle. */
    renderHandle?: (handle: ResizeHandleName) => ReactNode;
    handleClassName?: string;
    messages?: Partial<ResizeHandlesMessages>;
  };

export type ResizeHandlesContextValue = {
  rect: ResizeRect;
  resizing: boolean;
  messages: ResizeHandlesMessages;
};

export const ResizeHandlesContext = createContext<ResizeHandlesContextValue | null>(null);

/** The current rect and text of the nearest ResizeHandles, for custom parts. */
export function useResizeHandles() {
  const context = useContext(ResizeHandlesContext);
  if (!context) throw new Error("Resize handle parts must be rendered inside <ResizeHandles>.");
  return context;
}

"use client";

export { type ResizeDetail, type ResizeHandlesMessages, type ResizeHandlesProps, type ResizeTransform, useResizeHandles } from "./resize-handles-state";
export { ResizeHandles } from "./resize-handles-root";
export { ResizeHandlesLabel } from "./resize-handles-parts";
export { type ResizeEdges, type ResizeHandleName, type ResizeLimits, type ResizeOptions, type ResizePoint, type ResizeRect, type ResizeSnap, resizeRect } from "./resize-handles-math";
